/// <summary>
/// AVA/WEN 2024/04/09  AVA_011510_ThirdPartyGalvanizing
/// </summary>

class AVAThirdPartyGalvanizingController  extends SysOperationServiceController
{
}

Method.Source:
public static void main(Args _args)
{
    AVAThirdPartyGalvanizingController controller;
    SysOperationStartResult sysOperationStartResult;
    AVAThirdPartyGalvanizingContract dataContract;
    Set recordSet;
    SalesLine salesline;
    MultiSelectionHelper multiselectionHelper;

    controller = new AVAThirdPartyGalvanizingController();
    controller.parmArgs(_args);

    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    if (_args && _args.caller() is FormRun)
    {
        recordSet = new Set(Types::Record);
        multiselectionHelper = MultiSelectionHelper::createFromCaller(_args.caller());

        salesline = multiselectionHelper.getFirst();
        while (salesline)
        {
            recordSet.add(salesline);

            salesline = multiselectionHelper.getNext();
        }
    }

    dataContract = controller.getDataContractObject();
    if (dataContract is AVAThirdPartyGalvanizingContract)
    {
        dataContract.parmRecordCon(recordSet.pack());
    }

    sysOperationStartResult = controller.startOperation();
}

public boolean parmShowDialog(boolean _showDialog = showDialog)
{
    return false;
}
